import { z } from "zod";
import { defineAgent } from "../../runner/spec.ts";

// All audio is generated by code committed to the game repo (deterministic, licensed clean
// by construction) and registered in the asset manifest. No downloaded audio files.
export default defineAgent({
  name: "audio",
  description: "Audio: procedurally generates sound effects and music as committed code, registers every asset in the manifest, and documents the hooks Eng wires up.",
  dept: "audio",
  runner: "local",
  model: "z-ai/glm-5.3",
  budget: { cap_usd: 3, max_task_usd: 0.75, period: "day" },
  tools: { game_repo: "allow", workspace_read: "allow", workspace_write: "allow", studio_ledger: "allow" },
  output_schema: z
    .object({
      sounds: z
        .array(
          z
            .object({
              id: z.string().min(2).max(60).describe("Manifest entry id"),
              kind: z.enum(["sfx", "music", "ambient"]),
              file: z.string().max(200).describe("Path in the clone, e.g. assets/audio/hit.wav"),
              duration_s: z.number().positive().max(600).describe("From the generator output or file inspection, not guessed"),
              generator: z.string().max(200).describe("The committed script + parameters that produce it"),
              triggers: z.string().max(200).describe("Which events (events.md names) it should play on"),
            })
            .strict(),
        )
        .min(3)
        .max(20),
      generator_doc: z.string().max(120).describe("Where the regeneration instructions live, e.g. audio/README.md"),
      manifest_ok: z.boolean().describe("True only if you re-validated the manifest after your edits"),
      integration: z
        .array(z.object({ for: z.string().max(40).describe("Agent that must act, e.g. 'tech-lead'"), what: z.string().min(10).max(250) }).strict())
        .max(4)
        .describe("Event→sound hooks only Eng can wire; you don't edit gameplay scenes"),
    })
    .strict(),
  limits: { max_turns: 30, max_output_tokens: 8192 },
});
